// Writes the database setup as plain SQL to paste into Supabase › SQL Editor, for setting up a
// project without the Supabase CLI: every migration in order, recorded in supabase_migrations
// so a later `supabase db push` knows they're applied, and the sample catalog separately.
// The editor runs a pasted script as one transaction, so a failure leaves nothing half done.
//
//   npm run db:bundle                          supabase/setup/1-database.sql and 2-sample-data.sql
//   npm run db:bundle -- --since 20261022000100   only the migrations after that one (an update)
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const since = process.argv.includes("--since") ? process.argv[process.argv.indexOf("--since") + 1] : null;
if (since !== null && !/^\d{14}$/.test(since ?? "")) {
  console.error("--since takes a migration version, like 20261022000100");
  process.exit(1);
}

const migrations = readdirSync(join(root, "supabase/migrations"))
  .filter((f) => /^\d{14}_[a-z0-9_]+\.sql$/.test(f))
  .sort()
  .map((f) => ({ file: f, version: f.slice(0, 14), name: f.slice(15, -4) }))
  .filter((m) => !since || m.version > since);
if (!migrations.length) {
  console.error(since ? `No migrations after ${since}.` : "No migrations found.");
  process.exit(1);
}

const out = join(root, "supabase/setup");
mkdirSync(out, { recursive: true });
const parts = [
  since
    ? `-- Taana: database update (migrations after ${since}). Paste into Supabase › SQL Editor and Run, once.`
    : "-- Taana: database setup for a new Supabase project. Paste into Supabase › SQL Editor and Run, once.",
  "-- Generated by scripts/sql-bundle.mjs from supabase/migrations. Do not edit by hand.",
  "",
];
for (const m of migrations) {
  parts.push(`-- ===== ${m.file} =====`, readFileSync(join(root, "supabase/migrations", m.file), "utf8").trimEnd(), "");
}
parts.push(
  "-- Record the migrations the way the Supabase CLI does.",
  "create schema if not exists supabase_migrations;",
  "create table if not exists supabase_migrations.schema_migrations (version text primary key, statements text[], name text);",
  `insert into supabase_migrations.schema_migrations (version, name) values\n${migrations.map((m) => `  ('${m.version}', '${m.name}')`).join(",\n")}\non conflict (version) do nothing;`,
  "",
);
const database = join(out, since ? `update-after-${since}.sql` : "1-database.sql");
writeFileSync(database, parts.join("\n"));
console.log(`${database}: ${migrations.length} migrations`);

if (!since) {
  // One DO block: Supabase's SQL editor mangled the plain statements (text with a semicolon
  // inside quotes), while dollar-quoted code, like every function above, goes through intact.
  const seed = readFileSync(join(root, "supabase/seed.sql"), "utf8");
  if (seed.includes("$sample$")) throw new Error("seed.sql can't contain $sample$");
  const sample = join(out, "2-sample-data.sql");
  writeFileSync(
    sample,
    [
      "-- Taana: the sample catalog (products, photos, collections, discount codes). Optional: run it",
      "-- after 1-database.sql. Remove it before launch in Admin › Settings › Maintenance and data.",
      "-- Generated by scripts/sql-bundle.mjs from supabase/seed.sql.",
      "do $sample$",
      "begin",
      seed.trimEnd(),
      "end",
      "$sample$;",
      "",
    ].join("\n"),
  );
  console.log(`${sample}: sample catalog`);
}
